def encrypt(text):
# 加密
data = []
for i in text:
if i.isupper():
i = i.lower()
data.append(chr((ord(i)+1-97) % 26 + 97))
elif i.islower():
i = i.upper()
data.append(chr((ord(i)+1-65) % 26 + 65))
elif i.isdigit():
i = str((int(i) + 1) % 10)
data.append(i)
else:
data.append(i)
return ''.join(data)

def decrypt(text):
# 解密
data = []
for i in text:
if i.isupper():
i = i.lower()
data.append(chr((ord(i)-1-97) % 26 + 97))
elif i.islower():
i = i.upper()
data.append(chr((ord(i)-1-65) % 26 + 65))
elif i.isdigit():
i = str( (int(i) - 1) % 10)
data.append(i)
else:
data.append(i)
return ''.join(data)

