public class Angle {

//判断是否能构成三角形
public static int JudgeAngle(int a, int b, int c) {
if (a + b > c && a + c > b && b + c > a) {
System.out.println("能够构成三角形！");
return 1;
} else {
System.out.println("不能构成三角形!");
return 0;
}
}

//判断是否能构成等腰三角形
public static int JudgeDangle(int a, int b, int c) {
if (a == b || a == c || b == c) {
if (a == b && a == c) {
System.out.println("该三角形是等边三角形！");
return 1;
} else {
System.out.println("该三角形是普通的等腰三角形！");
return 1;
}
} else {
return 0;
}
}

//判断是否是直角三角形
public static int JudgeRangle(int a, int b, int c) {
int r1, r2, r3;
r1 = a * a + b * b - c * c;
r2 = a * a + c * c - b;
r3 = b * b + c * c - a * a;
/*System.out.println(r1+r2+r3);*/
if (r1 == 0 || r2 == 0 || r3 == 0) {
System.out.println("该三角形是直角三角形！");
return 1;
} else {
return 0;
}
}

public static void main(String[] args) {
int a;
int b;
int c;
System.out.println("请输入三角形的三边: ");
Scanner scanner = new Scanner(System.in);
a = scanner.nextInt();
b = scanner.nextInt();
c = scanner.nextInt();
//判断输入三边是否合法
if (a < 0 || a > 200 || b < 0 || b > 200 || c < 0 || c > 200) {
System.out.println("你输入的三边不合法！");
} else {
//判断是否能构成三角形
JudgeAngle(a, b, c);
//判断是否是等腰或等边三角形
JudgeDangle(a, b, c);
//判断是否是直角三角形
JudgeRangle(a, b, c);
//判断是一般三角形
System.out.println("该三角形是一般三角形!");
}
}

}

