CREATE OR REPLACE PROCEDURE calculate_tax AS
 money float;
 tax float;
 sale number;
 totalmoney number;
 lowmoney number;
 endmoney number;
BEGIN
 money := 0;
 tax := 0.01; --税
 sale := 1000; --销售量
 totalmoney := 4700; --总金额
 lowmoney := sale+1600; --最低金额
 endmoney := 0;

 WHILE lowmoney<=totalmoney LOOP
 money := money+sale*tax;
 tax := tax+0.001;
 lowmoney := lowmoney+sale;
 END LOOP;

 endmoney := totalmoney+sale-lowmoney;
 money := money+endmoney*tax;

 DBMS_OUTPUT.PUT_LINE('最终money值为: ' || money);
END calculate_tax;
/

