def find_repeat_char(s):
data = {}
for index, char in enumerate(s):
temp = data.get(char, [])
temp.append('{}, {}'.format(char, index+1))
data[char] = temp
res = []
for value in data.values():
if len(value) > 1:
res.extend(value)
return '; '.join(res)

