import re

def check(password):
if len(password) < 9:
return 'NG'
count = 0
if re.search('[a-z]', password):
count += 1
if re.search('[A-Z]', password):
count += 1
if re.search('[0-9]', password):
count += 1
if re.search('[^a-zA-Z0-9]', password):
count += 1
if count < 3:
return 'NG'
if re.search(r'.*?(...).*?\1.*?', password):
return 'NG'

return 'OK'

